import{_ as o,o as a,c as t,a2 as s}from"./chunks/framework.D7Ov6LBE.js";const u=JSON.parse('{"title":"Proposta — Sistema de Agendamento Universal","description":"","frontmatter":{},"headers":[],"relativePath":"projetos/agendamento-universal.md","filePath":"projetos/agendamento-universal.md","lastUpdated":null}'),n={name:"projetos/agendamento-universal.md"};function r(i,e,d,c,l,p){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="proposta-—-sistema-de-agendamento-universal" tabindex="-1">Proposta — Sistema de Agendamento Universal <a class="header-anchor" href="#proposta-—-sistema-de-agendamento-universal" aria-label="Permalink to &quot;Proposta — Sistema de Agendamento Universal&quot;">​</a></h1><blockquote><p><strong>Status: PROPOSTA — aguardando decisão</strong> · Documento-pivô da sessão de decisão <strong>Decisão pendente</strong>: aceitar / declinar / ajustar esta proposta.</p></blockquote><hr><h2 id="_1-contexto" tabindex="-1">1. Contexto <a class="header-anchor" href="#_1-contexto" aria-label="Permalink to &quot;1. Contexto&quot;">​</a></h2><p>A wiki do Ampla Vendas ERP nasceu como um teste de processo (fonte privada → build estático → GitHub Pages com domínio próprio) e <strong>provou a fundação inteira</strong>: o hub <code>docs.axio.eng.br/{projeto}</code> está pronto, o enforcement híbrido de documentação está validado, e o domínio de integração canônica (padrão Quanta) já foi exercitado no nexus-gateway.</p><p>A proposta a seguir reutiliza essa fundação para um <strong>produto novo, independente do Ampla</strong>: um sistema de agendamento completo, genérico (vertical-agnóstico), com o primeiro cliente sendo <strong>consultas médicas</strong>.</p><h2 id="_2-visao" tabindex="-1">2. Visão <a class="header-anchor" href="#_2-visao" aria-label="Permalink to &quot;2. Visão&quot;">​</a></h2><blockquote><p><strong>Objetivo final (norte do projeto):</strong><em>&quot;O melhor e simples sistema de agendamento possível para integrar no ecossistema ERP genérico.&quot;</em></p></blockquote><p>Desdobrado:</p><ul><li><strong>Simples primeiro</strong> — simplicidade é o princípio de design dominante, não um detalhe. Qualquer complexidade (pipeline, canônico, LLM) só entra se pagar o próprio custo.</li><li><strong>Integrar no ecossistema ERP genérico</strong> — o sistema é um <strong>componente integrado</strong>, não uma ilha: full duplex de tipos de dados com ERPs e sistemas adjacentes.</li><li><strong>Nada específico por ramo/setor</strong> no núcleo — o domínio canônico é neutro; setor entra por adaptador.</li><li><strong>Primeiro cliente</strong>: clínicas médicas (agendamento de consultas) — domínio que já dominamos.</li></ul><h2 id="_3-arquitetura-proposta" tabindex="-1">3. Arquitetura proposta <a class="header-anchor" href="#_3-arquitetura-proposta" aria-label="Permalink to &quot;3. Arquitetura proposta&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Decisão</th><th>Escolha</th><th>Justificativa</th></tr></thead><tbody><tr><td><strong>Formato</strong></td><td>Hexagonal (portas &amp; adaptadores)</td><td>Domínio puro e testável; adaptadores bijetivos; mesmo padrão validado no nexus-gateway</td></tr><tr><td><strong>Casos de uso</strong></td><td>Pipelines com steps tipados</td><td><code>AgendarConsulta</code>, <code>Remarcar</code>, <code>Cancelar</code>, <code>ConsultarDisponibilidade</code> — cada step testável isoladamente</td></tr><tr><td><strong>Concorrência</strong></td><td>UoW (unidade de trabalho) + lock no reserva de slot</td><td>Dois pacientes no mesmo horário / agenda web + recepção + WhatsApp simultâneos</td></tr><tr><td><strong>Canônico</strong></td><td>FHIR-inspired simplificado</td><td><code>Patient</code>, <code>Practitioner</code>, <code>Schedule</code>, <code>Slot</code>, <code>Appointment</code> — nasce falando o idioma do ecossistema de saúde; generaliza depois</td></tr><tr><td><strong>LLM (regras em pt-BR)</strong></td><td>Híbrido: design-time + runtime</td><td>Ver §4</td></tr></tbody></table><h3 id="exemplo-de-pipeline-—-agendarconsulta" tabindex="-1">Exemplo de pipeline — <code>AgendarConsulta</code> <a class="header-anchor" href="#exemplo-de-pipeline-—-agendarconsulta" aria-label="Permalink to &quot;Exemplo de pipeline — \`AgendarConsulta\`&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. ValidarPaciente          (porta de saída: cadastro)</span></span>
<span class="line"><span>2. CalcularDisponibilidade  (domínio puro: slots, buffers, janela, prioridade)</span></span>
<span class="line"><span>3. ReservarSlot             ⚠️ atômico + concorrência (UoW/lock)</span></span>
<span class="line"><span>4. Persistir + PublicarEvento (AgendaPort + EventoBusPort)</span></span>
<span class="line"><span>5. Notificar                (porta de saída: notificação)</span></span>
<span class="line"><span>6. SincronizarERP           (adapter full duplex: agenda/fatura no ERP)</span></span></code></pre></div><h2 id="_4-onde-o-llm-entra-o-diferencial" tabindex="-1">4. Onde o LLM entra (o diferencial) <a class="header-anchor" href="#_4-onde-o-llm-entra-o-diferencial" aria-label="Permalink to &quot;4. Onde o LLM entra (o diferencial)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Modo</th><th>Como funciona</th><th>Uso</th></tr></thead><tbody><tr><td><strong>Design-time (compilador)</strong></td><td>LLM lê regras em pt-BR (<em>&quot;retorno tem prioridade sobre 1ª consulta; janela de 7 dias; buffer de 15 min&quot;</em>) e <strong>gera a configuração determinística</strong> que o domínio executa</td><td>regras estruturais: disponibilidade, buffers, prioridades — auditável, testável (golden tests)</td></tr><tr><td><strong>Runtime (intérprete)</strong></td><td>LLM entra como <strong>step do pipeline</strong> para casos de borda</td><td>sugestão de horário alternativo na remarcação, triagem de conflito, resposta humanizada</td></tr></tbody></table><p><strong>Regra de pureza</strong>: o LLM fica <strong>fora do domínio</strong> — implementado atrás de uma <code>RegrasPort</code>; o domínio nunca depende de modelo de linguagem. Regras em pt-BR ficam versionadas como ativos do repo (<em>regras como código documentado</em>).</p><h2 id="_5-o-que-ja-esta-pago-heranca-da-fundacao" tabindex="-1">5. O que já está pago (herança da fundação) <a class="header-anchor" href="#_5-o-que-ja-esta-pago-heranca-da-fundacao" aria-label="Permalink to &quot;5. O que já está pago (herança da fundação)&quot;">​</a></h2><ul><li>[x] Hub de documentação <code>docs.axio.eng.br/{projeto}</code> — próximo projeto <strong>nasce com wiki publicada</strong> (só <code>--base /agendamento/</code> + pasta)</li><li>[x] Enforcement híbrido de docs (hook <code>--warn</code> / CI <code>--block</code>) — portátil para o novo repo</li><li>[x] Padrão Quanta / canônico + adaptadores bijetivos — validado no nexus-gateway</li><li>[x] Vocabulário do domínio clínico (intraclinica)</li></ul><h2 id="_6-riscos-decisoes-em-aberto" tabindex="-1">6. Riscos &amp; decisões em aberto <a class="header-anchor" href="#_6-riscos-decisoes-em-aberto" aria-label="Permalink to &quot;6. Riscos &amp; decisões em aberto&quot;">​</a></h2><ul><li>[ ] <strong>Concorrência</strong>: estratégia de lock (otimista vs pessimista) — decisão de ADR</li><li>[ ] <strong>Idempotência full duplex</strong>: como o ERP recebe eventos sem duplicar (webhooks + retry + dedup)</li><li>[ ] <strong>Linguagem/stack do runtime determinístico</strong> (ex.: TypeScript? Python? — decidir no ADR-002)</li><li>[ ] <strong>Custo LLM</strong>: design-time é barato (compila uma vez); runtime tem custo por chamada — definir limites</li><li>[ ] <strong>Repositório novo</strong> + kanban + wiki <code>docs.axio.eng.br/agendamento/</code></li></ul><h2 id="_7-proximos-passos-se-aceita" tabindex="-1">7. Próximos passos (se aceita) <a class="header-anchor" href="#_7-proximos-passos-se-aceita" aria-label="Permalink to &quot;7. Próximos passos (se aceita)&quot;">​</a></h2><ol><li><strong>ADR-001</strong> — hexagonal + pipeline UoW + canônico FHIR-inspired + LLM design-time/runtime</li><li><strong>Doc de visão</strong> (1 página) + <strong>diagrama ASCII</strong> da arquitetura</li><li>Repo novo + kanban + wiki do projeto</li><li><strong>Sem código ainda</strong> — decisões de arquitetura primeiro, código depois</li></ol><hr><p><em>Pivô: este documento é o ponto de partida da sessão de decisão. Discutir sobre o texto, não sobre a memória da conversa.</em></p>`,25)])])}const g=o(n,[["render",r]]);export{u as __pageData,g as default};
